const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const southTaiwan = ee.Geometry.Polygon([[
    [120.2, 22.0], [121.0, 22.0], [121.0, 23.5], [120.2, 23.5]
  ]]);
  const northTaiwan = ee.Geometry.Polygon([[
    [120.8, 24.0], [122.0, 24.0], [122.0, 25.5], [120.8, 25.5]
  ]]);

  const startDate = '2009-08-03';
  const endDate = '2009-08-10'; // GEE date range is exclusive at the end

  // 2. Data Acquisition & Check
  const trmmCollection = ee.ImageCollection('TRMM/3B42')
    .filterDate(startDate, endDate)
    .select('precipitation');

  const collectionSize = trmmCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log("Empty Collection: No TRMM images found for the specified date range.");
    console.log("A"); // C1
    return;
  }
  console.log(`Image count: ${collectionSize}`);

  // 3. Processing
  // The data is in mm/hr, and each image is a 3-hour accumulation.
  // To get total precipitation, we sum the rates and multiply by the time step (3 hours).
  const totalPrecipitation = trmmCollection.sum().multiply(3);

  // 4. Calculation
  const scale = 5000; // TRMM resolution is ~27km, 5km is safe

  const southStats = totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: southTaiwan,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const northStats = totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: northTaiwan,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const southPrecip = southStats['precipitation_mean'];
  const southPixels = southStats['precipitation_count'];
  const northPrecip = northStats['precipitation_mean'];
  const northPixels = northStats['precipitation_count'];

  // 5. Validation & Final Answer
  if (southPixels === 0) {
    console.log("No valid pixels found for Southern Taiwan.");
    console.log("C2");
    return;
  }
  if (northPixels === 0) {
    console.log("No valid pixels found for Northern Taiwan.");
    console.log("C2");
    return;
  }

  if (southPrecip === null || northPrecip === null || typeof southPrecip === 'undefined' || typeof northPrecip === 'undefined') {
    console.log("Calculation failed: result is null or undefined.");
    console.log(`South precip: ${southPrecip}, North precip: ${northPrecip}`);
    console.log("C3");
    return;
  }

  console.log(`Southern Taiwan avg rainfall (mm): ${southPrecip.toFixed(2)} (${southPixels} pixels)`);
  console.log(`Northern Taiwan avg rainfall (mm): ${northPrecip.toFixed(2)} (${northPixels} pixels)`);

  if (southPrecip > northPrecip) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
